expire.kernel_code:
pub fn expire(st: &Heater, now: u64) -> (Heater, Option<u8>) {
    match st.ctl {
        Ctl::Remote { expires } => {
            if now >= expires {
                (Heater { ctl: Ctl::Nobody, duty: st.duty }, Some(0))
            } else {
                (*st, None)
            }
        }
        _ => (*st, None),
    }
}

ssr_step.kernel_code:
pub fn ssr_step(st: &Ssr, cmd: Option<SsrCmd>, new_duty: Option<u8>) -> Ssr {
    let s1 = match cmd {
        Some(SsrCmd::Lock) => Ssr { locked: true, pattern: 0 },
        Some(SsrCmd::Unlock) => Ssr { locked: false, pattern: st.pattern },
        None => *st,
    };
    if s1.locked {
        s1
    } else {
        match new_duty {
            Some(d) => {
                if d <= 100 { Ssr { locked: false, pattern: d } } else { s1 }
            }
            None => s1,
        }
    }
}

SafetyOut.kernel_code:
pub enum SafetyOut {
    Nothing,
    LockOvertemp,
    LockMissing,
    Unlock,
}

Ctl.kernel_code:
pub enum Ctl {
    /// No remote or manual controller.
    Nobody,
    /// A remote controls the heater until `expires` (it must check in).
    Remote { expires: u64 },
    /// A device controls it manually (no expiry).
    Manual,
}

Heater.kernel_code:
pub struct Heater {
    pub ctl: Ctl,
    /// The duty last recorded.
    pub duty: u8,
}

duty_set.kernel_code:
pub fn duty_set(st: &Heater, m: &DutyMsg) -> (Heater, Handled, Effects) {
    if !m.utf8 {
        return (*st, Handled::Utf8, NO_EFFECTS);
    }
    if !m.parsed {
        return (*st, Handled::Invalid, NO_EFFECTS);
    }
    if m.duty > 100 {
        return (*st, Handled::Unexpected, NO_EFFECTS);
    }
    if !m.sender {
        return (*st, Handled::Invalid, NO_EFFECTS);
    }
    match m.control {
        Control::Manual => {
            // `transition_to_manual`: always possible.
            let changed = match st.ctl {
                Ctl::Manual => !m.same_manual,
                _ => true,
            };
            (
                Heater { ctl: Ctl::Manual, duty: m.duty },
                Handled::Ok,
                Effects { send: Some(m.duty), announce: changed, record_sender: changed },
            )
        }
        Control::Remote => match st.ctl {
            // A new remote announces itself.
            Ctl::Nobody | Ctl::Manual => (
                Heater { ctl: Ctl::Remote { expires: expires_after(m.now) }, duty: m.duty },
                Handled::Ok,
                Effects { send: Some(m.duty), announce: true, record_sender: true },
            ),
            Ctl::Remote { expires } => {
                if !m.same_remote {
                    (*st, Handled::Unexpected, NO_EFFECTS)
                } else if m.now >= expires {
                    // It failed to check in in time.
                    (*st, Handled::Unexpected, NO_EFFECTS)
                } else {
                    (
                        Heater { ctl: Ctl::Remote { expires: expires_after(m.now) }, duty: m.duty },
                        Handled::Ok,
                        Effects { send: Some(m.duty), announce: false, record_sender: false },
                    )
                }
            }
        },
        Control::Other => (*st, Handled::Unexpected, NO_EFFECTS),
        Control::Missing => (*st, Handled::Invalid, NO_EFFECTS),
    }
}

Ssr.kernel_code:
pub struct Ssr {
    pub locked: bool,
    /// The duty of the pattern being played.
    pub pattern: u8,
