on_reading.kernel_code:
pub fn on_reading(st: &Safety, valid: bool, t16: i32, ts: u64) -> (Safety, SafetyOut) {
    if !valid {
        return (*st, SafetyOut::Nothing);
    }
    let deadline = sat_add(ts, MISSING_WINDOW_US);
    if !st.locked && t16 >= LOCK_T16 {
        // (upstream checks the unlock next; it can not apply: the lock
        // needs >= 70 °C, the unlock < 30 °C)
        return (Safety { locked: true, deadline }, SafetyOut::LockOvertemp);
    }
    if st.locked && t16 < UNLOCK_T16 {
        return (Safety { locked: false, deadline }, SafetyOut::Unlock);
    }
    (Safety { locked: st.locked, deadline }, SafetyOut::Nothing)
}

pattern_on.kernel_code:
pub fn pattern_on(duty: u8, i: u32) -> bool {
    if duty > 100 || i >= STEPS {
        return false;
    }
    let d = duty as u32;
    (50 + d * (i + 1)) / 100 > (50 + d * i) / 100
}

sat_add.kernel_code:
fn sat_add(a: u64, b: u64) -> u64 {
    a.saturating_add(b)
}

Safety.kernel_code:
pub struct Safety {
    pub locked: bool,
    /// No valid reading by then locks the SSR.
    pub deadline: u64,
}

Handled.kernel_code:
pub enum Handled {
    Ok,
    Utf8,
    Invalid,
    Unexpected,
}

DutyMsg.kernel_code:
pub struct DutyMsg {
    /// The payload is UTF-8.
    pub utf8: bool,
    /// It parses as a `u8`.
    pub parsed: bool,
    pub duty: u8,
    /// A non-blank `device` property.
    pub sender: bool,
    pub control: Control,
    /// The sender is the remote in control (if a remote is).
    pub same_remote: bool,
    /// The sender is the device in manual control (if one is).
    pub same_manual: bool,
    pub now: u64,
}

Control.kernel_code:
pub enum Control {
    Manual,
    Remote,
    /// A `control` property with another value.
    Other,
    /// No `control` property.
    Missing,
}

on_missing.kernel_code:
pub fn on_missing(st: &Safety, now: u64) -> (Safety, SafetyOut) {
    let deadline = sat_add(now, MISSING_WINDOW_US);
    if !st.locked {
        (Safety { locked: true, deadline }, SafetyOut::LockMissing)
    } else {
        (Safety { locked: true, deadline }, SafetyOut::Nothing)
    }
}

Effects.kernel_code:
pub struct Effects {
    /// The duty sent to the SSR (`None`: none sent).
    pub send: Option<u8>,
    /// The controller changed (the buzzer sounds, the watch is told).
    pub announce: bool,
    /// Who controls the heater is now this sender (the app records its id).
    pub record_sender: bool,
}

